const rows = $input.all().map(i => i.json);

const out = rows.map(r => {
  const flags = [];

  // Required fields must not be empty
  for (const f of ['lead_id', 'email']) {
    if (!String(r[f] ?? '').trim()) flags.push(`missing_${f}`);
  }

  // Budget: "15k", "15000" and "15000.00" all mean the same thing
  const rawBudget = String(r.monthly_budget_usd ?? '').trim().toLowerCase().replace(/[$,\s]/g, '');
  const m = rawBudget.match(/^(\d+(?:\.\d+)?)(k)?$/);
  const budget_usd_parsed = m ? parseFloat(m[1]) * (m[2] ? 1000 : 1) : null;
  if (budget_usd_parsed === null) flags.push('budget_unparseable');

  // Information only, not reasons to reject on their own
  if (!String(r.website ?? '').trim()) flags.push('info_no_website');
  if (!String(r.company ?? '').trim()) flags.push('info_no_company');

  // Add your own checks here, one per thing you noticed in your manual pass.

  return { ...r, budget_usd_parsed, flags };
});

// Cross-row: the same email appearing again means the same person.
// The later row gets a flag naming the earlier lead_id.
const seen = {};
for (const r of out) {
  const key = String(r.email ?? '').trim().toLowerCase();
  if (!key) continue;
  if (seen[key]) r.flags.push(`repeat_of_${seen[key]}`);
  else seen[key] = r.lead_id;
}

return out.map(r => ({ json: r }));

const input = $('Build prompt').item.json;
const raw = $json.text ?? '';
let parsed = null, parse_error = null;

try { parsed = JSON.parse(raw.replace(/```json|```/g, '').trim()); }
catch (e) { parse_error = $json.error ? String($json.error) : e.message; }

const allowed = ['QUALIFY', 'NURTURE', 'REJECT', 'ESCALATE'];
let decision, reason, confidence, decided_by;

if (!parsed || !allowed.includes(parsed.decision) || typeof parsed.confidence !== 'number') {
  // Invalid or missing model output: fail safe to a human
  decision = 'ESCALATE';
  reason = 'Model output was invalid, so a human should review this lead.';
  confidence = 0;
  decided_by = 'fallback';
} else {
  ({ decision, reason, confidence } = parsed);
  decided_by = 'model';
}

const model_decision = parsed?.decision ?? null;

// Low confidence: never push an uncertain call through
if (decided_by === 'model' && confidence < 0.5) {
  reason = `Low confidence (${confidence}) on ${model_decision}: ${reason}`;
  decision = 'ESCALATE';
  decided_by = 'rule_low_confidence';
}

return { json: {
  lead_id: input.lead_id,
  decision,
  reason,
  confidence,
  decided_by,
  model_decision,
  code_flags: input.flags,
  model_risk_flags: parsed?.risk_flags ?? [],
  prompt_sent: input.user_prompt,
  raw_response: raw,
  parse_error
}};

const crypto = require('crypto');
const buf = await this.helpers.getBinaryDataBuffer(0, 'data');
const sha = crypto.createHash('sha256').update(buf).digest('hex');
return [{
  json: { fixture_sha256: sha, brief_version: '2026-07', run_started_at: new Date().toISOString() },
  binary: $input.first().binary
}];

return [{ json: {
  meta: $('Verify checksum').first().json,
  run_finished_at: new Date().toISOString(),
  leads: $input.all().map(i => i.json)
}}];

const { flags, ...lead } = $json;
const user_prompt =
`Code checks flagged: ${flags.length ? flags.join(', ') : 'none'}

<lead>
${JSON.stringify(lead, null, 2)}
</lead>`;
return { json: { ...$json, user_prompt } };
